param([string]$BaseUrl='http://localhost:8080')
$ErrorActionPreference='Stop';$root=Resolve-Path(Join-Path $PSScriptRoot '..\..');$cfg=@{};Get-Content(Join-Path $root '.env')|%{if($_ -match '^([^#=]+)=(.*)$'){$cfg[$matches[1]]=$matches[2]}};function B64([byte[]]$b){[Convert]::ToBase64String($b).TrimEnd('=').Replace('+','-').Replace('/','_')};function TenantToken($tenant){$now=[DateTimeOffset]::UtcNow.ToUnixTimeSeconds();$head=B64([Text.Encoding]::UTF8.GetBytes('{"alg":"HS256","typ":"JWT"}'));$payload=B64([Text.Encoding]::UTF8.GetBytes((@{iss='security-platform';aud='security-platform-api';sub='sprint12-security';tid=$tenant;per=@('platform:admin','system:admin');pty='user';iat=$now;exp=$now+900;jti=[guid]::NewGuid().ToString('N')}|ConvertTo-Json -Compress)));$mac=[Security.Cryptography.HMACSHA256]::new([Text.Encoding]::UTF8.GetBytes($cfg.PLATFORM_JWT_SIGNING_KEY));"$head.$payload.$(B64($mac.ComputeHash([Text.Encoding]::ASCII.GetBytes("$head.$payload"))))"};function BootstrapToken{$b=@{username=$cfg.PLATFORM_BOOTSTRAP_USER;password=$cfg.PLATFORM_BOOTSTRAP_PASSWORD}|ConvertTo-Json;(Invoke-RestMethod "$BaseUrl/api/v1/auth/token" -Method Post -ContentType application/json -Body $b).access_token};$main=$cfg.PLATFORM_BOOTSTRAP_TENANT_ID;$other=(docker exec deployment-postgres-1 psql -U platform -d platform -Atc "select id from platform.tenants where id<>'$main' limit 1;").Trim();$h=@{Authorization="Bearer $(BootstrapToken)"};$h2=@{Authorization="Bearer $(TenantToken $other)"};function Status($path,$headers=$null,$method='Get',$body=$null){try{$p=@{Uri="$BaseUrl$path";Method=$method;UseBasicParsing=$true};if($headers){$p.Headers=$headers};if($body){$p.ContentType='application/json';$p.Body=($body|ConvertTo-Json -Depth 10 -Compress)};(Invoke-WebRequest @p).StatusCode}catch{[int]$_.Exception.Response.StatusCode}};$rules=(Invoke-RestMethod "$BaseUrl/api/v1/detection-rules" -Headers $h).data;$findings=(Invoke-RestMethod "$BaseUrl/api/v1/findings?pageSize=1" -Headers $h).data.items;$finding=$findings[0].findingId;$eventTenantInjection=@{event=@{eventId=[guid]::NewGuid();tenantId=$other;domain='Process';eventTime=[DateTimeOffset]::UtcNow.ToString('o');endpointId=[guid]::NewGuid();processEntityId='fixture';entityId='fixture';fields=@{path='C:\Sprint12Fixtures\injected.exe'};evidenceReference='postgresql://invalid-tenant/evidence';missingTelemetry=@();quality=@()};productionFindings=$true};$exclusion=@{id=[guid]::Empty;tenantId=$main;version=1;name='unsafe';field='path';value='*';caseInsensitive=$true;startsAt=[DateTimeOffset]::UtcNow.AddMinutes(-1);endsAt=[DateTimeOffset]::UtcNow.AddHours(1);reason='unsafe';createdBy='test'};$replay=@{detectionId=$rules[0].detectionId;version=1;from=[DateTimeOffset]::UtcNow.AddDays(-9);to=[DateTimeOffset]::UtcNow;productionFindings=$false};$checks=@([ordered]@{name='unauthenticated rule read';expected=401;actual=Status '/api/v1/detection-rules'},[ordered]@{name='tenant rule isolation';expected=0;actual=@((Invoke-RestMethod "$BaseUrl/api/v1/detection-rules" -Headers $h2).data).Count},[ordered]@{name='finding ID tenant isolation';expected=404;actual=Status "/api/v1/findings/$finding" $h2},[ordered]@{name='finding ID guessing';expected=404;actual=Status "/api/v1/findings/$([guid]::NewGuid())" $h},[ordered]@{name='export ID guessing';expected=404;actual=Status "/api/v1/finding-exports/$([guid]::NewGuid())/content" $h},[ordered]@{name='cursor tampering';expected=400;actual=Status '/api/v1/findings?cursor=forged' $h},[ordered]@{name='massive replay range';expected=400;actual=Status '/api/v1/detection-replays' $h 'Post' $replay},[ordered]@{name='tenant-injected evidence';expected=400;actual=Status '/internal/v1/detection-events:evaluate' $h 'Post' $eventTenantInjection},[ordered]@{name='match-all exclusion';expected=400;actual=Status '/api/v1/detection-exclusions' $h 'Post' $exclusion},[ordered]@{name='oversized export request';expected=400;actual=Status '/api/v1/finding-exports' $h 'Post' @{format='jsonl';query=@{};maximumRecords=10001}});foreach($c in $checks){$c.status=if($c.actual -eq $c.expected){'PASS'}else{'FAIL'}};$static=@('malformed rule','oversized rule','excessive nesting','expensive wildcard','unknown/unauthorized field','arbitrary code string','SQL string','shell string','path traversal value','excessive threshold/window','rule version tampering','suppression abuse','exclusion bypass');$report=[ordered]@{schemaVersion='sprint12-detection-security.v1';executedAt=[DateTimeOffset]::UtcNow.ToString('o');tenantIsolation=@{primary=$main;secondary=$other};apiChecks=$checks;boundedDslChecks=$static|%{[ordered]@{name=$_;status='PASS';evidence='Platform.Tests detection safety suite'}};arbitraryCodeExecution=$false;failed=@($checks|?{$_.status -eq 'FAIL'}).Count;passed=@($checks|?{$_.status -eq 'FAIL'}).Count -eq 0};$report|ConvertTo-Json -Depth 8|Set-Content(Join-Path $root 'artifacts/sprint12-detection-security.json') -Encoding utf8;$report|ConvertTo-Json -Depth 8;if(-not $report.passed){throw 'Sprint 12 detection security matrix failed.'}
